def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_o = opp[-1]

    opp_d = 0
    my_d = 0
    ever_dd = False
    for i in range(n):
        m = me[i]
        o = opp[i]
        if m == 'D':
            my_d += 1
            if o == 'D':
                ever_dd = True
        if o == 'D':
            opp_d += 1

    streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            streak += 1
        else:
            break

    c_to_c = 0
    c_to_d = 0
    d_to_c = 0
    d_to_d = 0
    start = n - 15
    if start < 0:
        start = 0
    for i in range(start, n - 1):
        if me[i] == 'C':
            if opp[i + 1] == 'C':
                c_to_c += 1
            else:
                c_to_d += 1
        else:
            if opp[i + 1] == 'C':
                d_to_c += 1
            else:
                d_to_d += 1

    opp_rate = opp_d / n if n > 0 else 0.0

    if c_to_c + c_to_d > 0:
        pc = c_to_d / (c_to_c + c_to_d)
    else:
        pc = opp_rate

    if d_to_c + d_to_d > 0:
        pd = d_to_d / (d_to_c + d_to_d)
    else:
        pd = opp_rate

    if last_o == 'D':
        if streak >= 4:
            return 'D'

        if n >= 18 and 0.30 <= opp_rate <= 0.55 and pd <= opp_rate + 0.15:
            return 'D'

        return 'C'

    if my_d == 0 and opp_d == 0:
        if n >= 25:
            return 'D'
        return 'C'

    if d_to_d == 0 and d_to_c >= 1 and not ever_dd and my_d >= 1 and opp_d <= 4 and n >= 15:
        return 'D'

    if pd + 0.15 < pc:
        return 'D'

    if n >= 18 and 0.30 <= opp_rate <= 0.55 and pd <= opp_rate + 0.15:
        return 'D'

    return 'C'
